/**
 * Fast tableless/branchless IEEE 802.3 CRC32 verification helper.
 * Zero RAM lookup table required, ideal for IRAM / cache-constrained microcontrollers.
 */
[[nodiscard]] constexpr uint32_t petbot_crc32(
    const uint8_t* data,
    size_t length,
    uint32_t initial = 0xFFFFFFFFU
) noexcept {
    uint32_t crc = initial;
    for (size_t i = 0; i < length; ++i) {
        crc ^= static_cast<uint32_t>(data[i]);
        for (int b = 0; b < 8; ++b) {
            crc = (crc >> 1) ^ (0xEDB88320U & -(crc & 1U));
        }
    }
    return ~crc;
}
